#!/bin/bash
set -euxo pipefail
apt-get update
DEBIAN_FRONTEND=noninteractive apt-get install -y apache2 libapache2-mod-wsgi-py3 python3-flask sqlite3
mkdir -p /var/www/awsapp/uploads
base64 -d > /var/www/awsapp/app.py <<'EOF'

EOF
base64 -d /var/www/awsapp/app.py > /var/www/awsapp/app.tmp
mv /var/www/awsapp/app.tmp /var/www/awsapp/app.py
cat > /var/www/awsapp/awsapp.wsgi <<'EOF'
import sys
sys.path.insert(0, '/var/www/awsapp')
from app import app as application
EOF
chown -R www-data:www-data /var/www/awsapp
chmod -R 755 /var/www/awsapp
cat > /etc/apache2/sites-available/awsapp.conf <<'EOF'
<VirtualHost *:80>
WSGIDaemonProcess awsapp python-path=/var/www/awsapp
WSGIProcessGroup awsapp
WSGIScriptAlias / /var/www/awsapp/awsapp.wsgi
<Directory /var/www/awsapp>
Require all granted
</Directory>
</VirtualHost>
EOF
a2dissite 000-default.conf
a2ensite awsapp.conf
systemctl restart apache2
